import base64, time, pyautogui
_text = base64.b64decode('Y2F0ICIvaG9tZS91c2VyL0RvY3VtZW50cy9Qcm9qZWN0cy9UaHJlYXRfTGV2ZWxfTWlkbmlnaHRfU2VxdWVsX05vdGVzLnR4dCI=').decode('utf-8')
try:
    import pyperclip
    pyperclip.copy(_text)
    time.sleep(0.1)
    pyautogui.hotkey('ctrl', 'v')
    time.sleep(0.1)
except Exception:
    _text = _text.replace('\r\n', '\n').replace('\r', '\n')
    for _line_index, _line in enumerate(_text.split('\n')):
        for _part_index, _part in enumerate(_line.split('\t')):
            if _part:
                pyautogui.typewrite(_part)
            if _part_index < len(_line.split('\t')) - 1:
                pyautogui.press('tab')
        if _line_index < len(_text.split('\n')) - 1:
            pyautogui.press('enter')

